// GENERADO por scripts/generar_calendario_fechas.mjs -- no editar a mano.
// Fuente: data/calendarios_espn/**.json (fechas reales de ESPN).
//
// A diferencia de realCalendar.ts, que ubicaba cada partido en una SEMANA, acá cada uno tiene su
// FECHA EXACTA. Es lo que permite que un club juegue liga el domingo y copa el jueves de la misma
// semana -- con el modelo por semanas esos partidos no tenían dónde entrar y los torneos no
// cerraban.

export type CompetitionKind =
  | 'league'
  | 'domestic_cup'
  | 'continental_cup'
  | 'national_tournament';

export interface DatedMatch {
  /** Fecha real del partido, YYYY-MM-DD. */
  date: string;
  home: string;
  away: string;
  /** Ronda, solo en las copas cargadas desde Transfermarkt ("Octavos de Final", "Semifinal (Ida)"). */
  round?: string;
}

export interface DatedCompetition {
  id: string;
  name: string;
  kind: CompetitionKind;
  /**
   * Copa cuyo calendario viene de OTRA temporada y sólo sirve para saber que el torneo existe y
   * quiénes lo juegan: sus partidos NO se emiten como fechas.
   *
   * La Copa MX cargada es de 2018 y la Copa Chile de 2025; corriéndoles los años para alinearlas
   * con la carrera, sus fechas caen en cualquier lado respecto de la liga -- medido, 23 choques de
   * menos de dos días entre Copa MX y Liga MX, y 11 entre Copa Chile y su liga. El torneo se juega
   * igual: el calendario le RESERVA días eligiéndolos contra el calendario propio de cada club, que
   * es justamente lo que respeta el descanso.
   */
  soloReservas?: boolean;
  /** Solo en ligas y copas nacionales: el valor de Club.league al que pertenece. */
  league?: string;
  firstDate: string | null;
  lastDate: string | null;
  matches: DatedMatch[];
}

